'use strict';
// Local simulation only. Real balances and schedules require an authoritative server.
const Economy=(()=>{
const MIN=60000,HOUR=3600000,ZONE=8*HOUR;
const JOBS=[['便利商店理貨','整理貨架、點貨，讓鄰居買得安心。','tiger-police'],['廟口環境巡檢','沿著老街巡視，協助店家整理環境。','bear-warden'],['工地物料整理','穿好防護裝備，協助工班搬運材料。','boar-builder'],['重機現場支援','協助機具調度與現場施工紀錄。','ox-demolition'],['港口設備維護','在海風中，完成今日的設備保養。','leopard-welder'],['山城救護站助理','補充救護用品，支援救護站日常。','rabbit-medic'],['社區健康站接待','協助居民報到與整理衛教資料。','deer-nurse'],['醫療物資盤點','確認物資清單，讓醫護安心值勤。','cat-surgeon'],['農田無人機巡查','檢查田區影像，紀錄作物狀態。','otter-drone'],['智慧街區測試','測試智慧設備，整理訊號紀錄。','fox-engineer'],['晶圓資料整理','核對產線資料，支援工程師作業。','owl-chip'],['城市設施巡查','檢查公共設施，記錄待維護項目。','rhino-commander']];
const ITEMS=[{id:'bolt',name:'備用螺帽',icon:'⚙',sell:25},{id:'badge',name:'復古徽章',icon:'✦',sell:80},{id:'cable',name:'完好傳輸線',icon:'⌁',sell:45},{id:'cup',name:'陶製小茶杯',icon:'♨',sell:120},{id:'postcard',name:'寶島明信片',icon:'▧',sell:60},{id:'chip',name:'紀念晶片',icon:'▣',sell:220}];
const GOODS=[{id:'tea',name:'冰涼烏龍茶',icon:'🍵',price:100,energy:10,desc:'喝口茶，歇一會兒。'},{id:'rice',name:'台式飯糰',icon:'🍙',price:250,energy:30,desc:'一顆飯糰，補足打拚的力氣。'},{id:'bento',name:'鐵路便當',icon:'🍱',price:400,energy:50,desc:'滿滿菜色，讓下一班工作有精神。'}];
const PRIZES=[{id:'a',name:'A賞・寶島虎虎公仔',icon:'🐯',sell:2500,weight:1},{id:'b',name:'B賞・海島風景擺飾',icon:'🏝',sell:600,weight:4},{id:'c',name:'C賞・職人隨行杯',icon:'☕',sell:180,weight:20},{id:'d',name:'D賞・城市小吊飾',icon:'🎐',sell:60,weight:75}];
const STOCKS=[{id:'9001',name:'島嶼晶圓',sector:'半導體',base:12850},{id:'9002',name:'港灣物流',sector:'航運物流',base:4280},{id:'9003',name:'山海食研',sector:'食品生技',base:7630},{id:'9004',name:'寶島能源',sector:'綠色能源',base:9550},{id:'9005',name:'旺來文創',sector:'文化創意',base:2860}];
const BINGO_PAY={1:{1:3},2:{2:12},3:{2:2,3:35},4:{2:1,3:5,4:100},5:{3:3,4:20,5:300},6:{3:1,4:8,5:60,6:1000},7:{4:3,5:20,6:150,7:3000},8:{4:2,5:10,6:60,7:600,8:10000},9:{5:5,6:30,7:200,8:2000,9:30000},10:{5:3,6:15,7:100,8:800,9:8000,10:50000}};
function seeded(str){let h=2166136261;for(const c of String(str)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
const int=(rng,n)=>Math.floor(rng()*n);
function sample(max,count,rng=Math.random){const a=Array.from({length:max},(_,i)=>i+1);for(let i=a.length-1;i>0;i--){const j=int(rng,i+1);[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,count);}
function offers(rng=Math.random){return sample(JOBS.length,3,rng).map((n,i)=>{const stars=1+int(rng,5);return {uid:`${Date.now()}-${i}-${int(rng,100000)}`,job:n-1,stars,rate:[0,30,55,90,140,220][stars],energy:stars};});}
function initial(old={},now=Date.now(),rng=Math.random){return {version:3,city:old.city||null,cash:Number.isFinite(old.gold)?Math.max(0,old.gold):3600,energy:Math.min(100,Math.max(0,old.energy??100)),energyAt:old.energyAt||now,exp:old.xp||0,tax:old.rep||0,premium:old.premium||0,donated:old.donated||0,facility:old.facility||[1,1,1],seed:String(int(rng,2147483647)),offers:offers(rng),job:null,jobResult:null,inventory:{},food:{tea:1},collectibles:{},tickets:[],ledger:[],holdings:{},market:{hour:Math.floor(now/HOUR),prices:Object.fromEntries(STOCKS.map(s=>[s.id,s.base])),history:Object.fromEntries(STOCKS.map(s=>[s.id,[s.base]]))},lastSlots:null};}
function log(st,text,delta=0,now=Date.now()){st.ledger.unshift({text,delta,at:now});st.ledger=st.ledger.slice(0,50);}
function energy(st,now){if(st.energy>=100){st.energy=100;st.energyAt=now;return;}const n=Math.floor(Math.max(0,now-st.energyAt)/(5*MIN));if(n>0){st.energy=Math.min(100,st.energy+n);st.energyAt+=n*5*MIN;if(st.energy===100)st.energyAt=now;}}
function round(type,now=Date.now()){const period=type==='bingo'?5*MIN:12*HOUR;const id=Math.floor((now+ZONE)/period);return {id,end:(id+1)*period-ZONE,period};}
function draw(type,id,seed){const a=sample(type==='bingo'?80:49,type==='bingo'?20:7,seeded(seed+':'+type+':'+id));return type==='bingo'?{numbers:a,super:a[19]}:{numbers:a.slice(0,6),special:a[6]};}
function payout(ticket,result){if(ticket.type==='lotto'){const hits=ticket.numbers.filter(n=>result.numbers.includes(n)).length,special=ticket.numbers.includes(result.special);let prize=0,tier='未中獎';if(hits===6){prize=10000000;tier='頭獎';}else if(hits===5&&special){prize=1000000;tier='貳獎';}else if(hits===5){prize=100000;tier='參獎';}else if(hits===4&&special){prize=10000;tier='肆獎';}else if(hits===4){prize=2000;tier='伍獎';}else if(hits===3&&special){prize=1000;tier='陸獎';}else if(hits===2&&special){prize=400;tier='柒獎';}else if(hits===3){prize=400;tier='普獎';}return {prize,tier,hits};}
let multiplier=0,hits=0;const mode=ticket.mode;if(mode==='basic'){hits=ticket.numbers.filter(n=>result.numbers.includes(n)).length;multiplier=BINGO_PAY[ticket.numbers.length]?.[hits]||0;}else if(mode==='super'){hits=ticket.numbers[0]===result.super?1:0;multiplier=hits?50:0;}else{const predicate=mode==='small'?n=>n<=40:mode==='big'?n=>n>=41:mode==='odd'?n=>n%2===1:n=>n%2===0;hits=result.numbers.filter(predicate).length;multiplier=hits>=13?5:0;}return {prize:ticket.stake*multiplier,hits,tier:multiplier?`${multiplier} 倍`:'未中獎'};}
function marketTick(st,now){const hour=Math.floor(now/HOUR);if(hour<=st.market.hour)return;for(let h=st.market.hour+1;h<=hour;h++){for(const stock of STOCKS){const rng=seeded(st.seed+':market:'+stock.id+':'+h),change=(int(rng,2001)-1000)/10000;const price=Math.max(100,Math.min(10000000,Math.round(st.market.prices[stock.id]*(1+change))));st.market.prices[stock.id]=price;st.market.history[stock.id].push(price);st.market.history[stock.id]=st.market.history[stock.id].slice(-24);}}st.market.hour=hour;}
function settle(st,now=Date.now()){energy(st,now);marketTick(st,now);if(st.job&&now>=st.job.end){const job=st.job;const rng=seeded(st.seed+':job:'+job.uid);const drops=[];if(rng()<.85){const count=1+int(rng,Math.min(3,job.stars));for(let i=0;i<count;i++){const item=ITEMS[int(rng,ITEMS.length)];st.inventory[item.id]=(st.inventory[item.id]||0)+1;drops.push(item.id);}}const pay=job.rate*job.minutes;st.cash+=pay;st.exp+=job.stars*job.minutes*5;st.tax+=Math.floor(pay*.05);st.jobResult={...job,pay,drops};st.job=null;log(st,'完成 '+JOBS[job.job][0],pay,now);}
for(const t of st.tickets){if(t.status!=='pending'||t.end>now)continue;const result=draw(t.type,t.round,st.seed),award=payout(t,result);t.status='settled';t.result=result;t.award=award;st.cash+=award.prize;log(st,(t.type==='bingo'?'賓果':'大樂透')+'第 '+t.round+' 期 '+award.tier,award.prize,now);}st.tickets=st.tickets.filter(t=>t.status==='pending').concat(st.tickets.filter(t=>t.status==='settled').slice(-40));return st;}
function accept(st,uid,minutes,now=Date.now()){settle(st,now);const o=st.offers.find(x=>x.uid===uid);if(st.job||st.jobResult)throw Error('請先完成或確認目前工作');if(!o||![1,5,10,30].includes(minutes))throw Error('請選擇有效工作與時長');const cost=o.energy*minutes;if(st.energy<cost)throw Error('體力不足，可到商店補充');st.energy-=cost;st.job={...o,minutes,start:now,end:now+minutes*MIN};st.offers=[];log(st,'接下 '+JOBS[o.job][0],0,now);return st.job;}
function finishNotice(st,rng=Math.random){if(!st.jobResult)return;st.jobResult=null;st.offers=offers(rng);}
function bet(st,type,mode,numbers,stake,now=Date.now()){settle(st,now);if(!['bingo','lotto'].includes(type))throw Error('遊戲不存在');const n=[...new Set(numbers)].sort((a,b)=>a-b);if(type==='lotto'){if(n.length!==6||n.some(x=>!Number.isInteger(x)||x<1||x>49))throw Error('請選 6 個不重複的號碼');stake=50;}else{if(!['basic','super','small','big','odd','even'].includes(mode))throw Error('請選有效玩法');if(![10,50,100].includes(stake))throw Error('請選有效金額');if(['basic','super'].includes(mode)){if(n.length<1||n.length>(mode==='super'?1:10)||n.some(x=>!Number.isInteger(x)||x<1||x>80))throw Error('號碼選擇不符合規則');}}
if(st.cash<stake)throw Error('遊戲新台幣不足');if(st.tickets.filter(t=>t.status==='pending').length>=100)throw Error('待開獎紀錄已滿，請等候結算');const r=round(type,now);st.cash-=stake;const t={id:`${now}-${st.tickets.length}`,type,mode,numbers:n,stake,round:r.id,end:r.end,status:'pending'};st.tickets.push(t);log(st,(type==='bingo'?'賓果選號':'大樂透選號')+' 第 '+r.id+' 期',-stake,now);return t;}
function slots(st,rng=Math.random,now=Date.now()){if(st.cash<50)throw Error('需要 50 遊戲新台幣');const icons=['🥟','🐯','🐔','🍵','🧧','🍍','🏮','⭐'];const reels=Array.from({length:3},()=>int(rng,8));const same=reels.every(x=>x===reels[0]);const mult=same?[60,120,40,20,30,20,20,10][reels[0]]:0;const prize=50*mult;st.cash+=prize-50;st.lastSlots={reels:reels.map(x=>icons[x]),prize,mult,at:now};log(st,same?'餃子老虎雞連線 '+mult+' 倍':'餃子老虎雞 未連線',prize-50,now);return st.lastSlots;}
function buy(st,id,qty){const g=GOODS.find(x=>x.id===id);if(!g||!Number.isInteger(qty)||qty<1||qty>99)throw Error('請選有效商品數量');const cost=g.price*qty;if(st.cash<cost)throw Error('遊戲新台幣不足');st.cash-=cost;st.food[id]=(st.food[id]||0)+qty;log(st,'購買 '+g.name+' ×'+qty,-cost);}
function use(st,id,now=Date.now()){energy(st,now);const g=GOODS.find(x=>x.id===id);if(!g||!st.food[id])throw Error('背包沒有這項補給');if(st.energy===100)throw Error('體力已滿，補給保留在背包');if(st.energy+g.energy>100)throw Error('會超過體力上限，請使用較小份補給');st.food[id]--;st.energy+=g.energy;if(st.energy===100)st.energyAt=now;log(st,'使用 '+g.name+'，體力 +'+g.energy);}
function sell(st,id,kind='item'){const item=(kind==='prize'?PRIZES:ITEMS).find(x=>x.id===id),bag=kind==='prize'?st.collectibles:st.inventory;if(!item||!bag[id])throw Error('背包沒有這項物品');bag[id]--;st.cash+=item.sell;log(st,'出售 '+item.name,item.sell);}
function ichiban(st,rng=Math.random){if(st.cash<200)throw Error('需要 200 遊戲新台幣');let x=rng()*100,p=PRIZES[3];for(const item of PRIZES){x-=item.weight;if(x<0){p=item;break;}}st.cash-=200;st.collectibles[p.id]=(st.collectibles[p.id]||0)+1;log(st,'一番賞 '+p.name,-200);return p;}
function trade(st,id,side,qty,now=Date.now()){settle(st,now);if(!STOCKS.some(s=>s.id===id)||!['buy','sell'].includes(side)||!Number.isInteger(qty)||qty<1||qty>100000)throw Error('請輸入有效交易數量');const price=st.market.prices[id],totalCents=price*qty;const cashCents=Math.round(st.cash*100);const holding=st.holdings[id]||{qty:0,costCents:0};if(side==='buy'){if(cashCents<totalCents)throw Error('遊戲新台幣不足');st.cash=(cashCents-totalCents)/100;holding.qty+=qty;holding.costCents+=totalCents;}else{if(holding.qty<qty)throw Error('持股數量不足');const costRemoved=Math.round(holding.costCents*qty/holding.qty);holding.qty-=qty;holding.costCents-=costRemoved;if(!holding.qty)holding.costCents=0;st.cash=(cashCents+totalCents)/100;}st.holdings[id]=holding;log(st,(side==='buy'?'買入 ':'賣出 ')+id+' ×'+qty+' 股',(side==='buy'?-1:1)*totalCents/100,now);return {price:price/100,total:totalCents/100};}
return {MIN,HOUR,JOBS,ITEMS,GOODS,PRIZES,STOCKS,BINGO_PAY,seeded,sample,offers,initial,energy,round,draw,payout,marketTick,settle,accept,finishNotice,bet,slots,buy,use,sell,ichiban,trade,log};})();
